window.PA_PASHA=[{"slug": "zaklinateli", "title": "Заклинатели", "meta": "Дикси · игра · 2024", "awards": "Silver Mercury 2025 — золото (D16 Best Gamification) · Red Apple 2025 — бронза (наилучшее использование цифровых инструментов) + 5 шорт-листов", "role": "creative group head — собирал идею, дожимал и защищал", "Задача": "Ритейлеру нужно вырасти по частоте покупок в семьях с детьми. Коллекции игрушек в категории стали фоном: ребёнок собирает, но не вовлекается, а родитель из-за этого магазин не меняет.", "Ограничения": "Игра должна была работать как механика акции, а не как имиджевый спецпроект: карточки, AR и мини-апп собирались под дату старта акции в сети, сдвиг невозможен.", "Решение": "Не коллекция, а первая в России полноценная игра от супермаркета. Вселенная «Астралис», 26 карточек героев и артефактов, AR-оживление, мини-апп для сборки своего персонажа.", "Результат": "Тендер выигран. Категории «игра от ритейлера» на рынке до этого не существовало — прецедент создан.", "video": [{"src": "media/zaklinateli/zaklinateli.mp4", "poster": "media/zaklinateli/zaklinateli.jpg"}, {"src": "media/zaklinateli/zaklinateli-cinema.mp4", "poster": "media/zaklinateli/zaklinateli-cinema.jpg"}], "blocks": [{"t": "img", "src": "media/zaklinateli/01.jpg", "w": 1600, "h": 602}, {"t": "img", "src": "media/zaklinateli/02.jpg", "w": 824, "h": 1600}, {"t": "img", "src": "media/zaklinateli/03.jpg", "w": 1505, "h": 1600}, {"t": "img", "src": "media/zaklinateli/04.jpg", "w": 1600, "h": 450}, {"t": "loop", "src": "media/zaklinateli/05.mp4"}, {"t": "img", "src": "media/zaklinateli/06.jpg", "w": 926, "h": 1600}, {"t": "img", "src": "media/zaklinateli/07.jpg", "w": 1600, "h": 1509}, {"t": "img", "src": "media/zaklinateli/08.jpg", "w": 1128, "h": 1600}, {"t": "img", "src": "media/zaklinateli/09.jpg", "w": 1600, "h": 1154}, {"t": "img", "src": "media/zaklinateli/10.jpg", "w": 1600, "h": 249}], "dprofile": "https://dprofile.ru/case/129988/zaklinateli", "thumb": "thumbs/zaklinateli.jpg"}, {"slug": "xroniki-izory", "title": "Хроники Ижоры", "meta": "ФК «Зенит» · сага · 2025", "awards": "Silver Mercury СЗФО 2026 — золото (Best Craft of Design) · серебро (Best Creative Project) · бронза (Best Digital Project)", "role": "creative group head — концепция вселенной и супервайзинг продакшна", "Задача": "Столетие клуба. Юбилей обычно закрывают роликом-открыткой, которую посмотрят один раз, — нужна была история, к которой возвращаются.", "Ограничения": "Столетний архив клуба: каждая историческая деталь согласовывалась. Всё собиралось под фиксированную дату юбилея.", "Решение": "Мультимедийная сага: славянское фэнтези × азиатская манхва, вертикальный вебтун, реальные игроки как герои магической истории, бренды интегрированы визуальными артефактами.", "Результат": "Юбилей превращён во вселенную, которую можно продолжать. Три медали за один проект.", "video": [], "blocks": [{"t": "img", "src": "media/xroniki-izory/01.jpg", "w": 1600, "h": 900}, {"t": "text", "text": "В честь столетия Клуба мы создали мультимедийную сагу «Хроники Ижоры».\nИстория в стиле славянского фэнтези и манхвы\nо Семаге и его воинах доступна в трех форматах: комикс-вебтун, аудиосказка и анимированный фильм."}, {"t": "img", "src": "media/xroniki-izory/02.jpg", "w": 1600, "h": 900}, {"t": "embed", "src": "https://kinescope.io/embed/9DQxue1yrRhG8YLgTs5Efn"}, {"t": "embed", "src": "https://kinescope.io/embed/fVjxNjRHPTd6Bg3oCFtL13"}, {"t": "img", "src": "media/xroniki-izory/03.jpg", "w": 1600, "h": 1336}, {"t": "img", "src": "media/xroniki-izory/04.jpg", "w": 967, "h": 1600}, {"t": "img", "src": "media/xroniki-izory/05.jpg", "w": 1600, "h": 940}, {"t": "img", "src": "media/xroniki-izory/06.jpg", "w": 1013, "h": 1600}, {"t": "img", "src": "media/xroniki-izory/07.jpg", "w": 1600, "h": 166}, {"t": "row", "items": [{"t": "img", "src": "media/xroniki-izory/08.jpg", "w": 900, "h": 1600}, {"t": "img", "src": "media/xroniki-izory/09.jpg", "w": 900, "h": 1600}, {"t": "img", "src": "media/xroniki-izory/10.jpg", "w": 900, "h": 1600}]}, {"t": "img", "src": "media/xroniki-izory/11.jpg", "w": 1600, "h": 166}, {"t": "img", "src": "media/xroniki-izory/12.jpg", "w": 871, "h": 1600}, {"t": "img", "src": "media/xroniki-izory/13.jpg", "w": 1522, "h": 1600}, {"t": "row", "items": [{"t": "img", "src": "media/xroniki-izory/14.jpg", "w": 900, "h": 1600}, {"t": "img", "src": "media/xroniki-izory/15.jpg", "w": 900, "h": 1600}, {"t": "img", "src": "media/xroniki-izory/16.jpg", "w": 900, "h": 1600}]}, {"t": "img", "src": "media/xroniki-izory/17.jpg", "w": 921, "h": 1600}, {"t": "img", "src": "media/xroniki-izory/18.jpg", "w": 1002, "h": 1600}, {"t": "text", "text": "**ФК «Зенит»**\nАлександр Медведев\nАлексей Пак\nЖанна Дембо\nИлья Балакирев\nАлександр Жаврид\nЕлена Бибикова \nИлья Ускорников\nАртем Петров\nПавел Ваулин\n\n**Яндекс Плюс и Кинопоиск**\nАлександр Решетов \nБорис Кочкин \nВероника Соколова\nЕкатерина Шестакова\n\n**Команда проекта**\nCreative Director: Андрей Яхновец\nРежиссер, автор сценария: Айгуль Бурганова\nХудожник: Ioanna Rvn\nЦвет: Elyn Gontie\nArt-director: Антон Фрос\nCreative Group Head: Павел Черкун\nЗвук: Роман Фокин\n\nMotion designer: Ксения Поливанова\nMotion designer: Ольга Подшибякина\nMotion designer: Елена Клюева\nMotion designer: Наталья Жукова\nТитры: Денис Деко\nИсполнительный продюсер: Сабина Зайнуллина\nАссистент продюсера: София Соколова-Сапожникова\nОператор-постановщик: Игорь Петрухин\nМеханик: Владислав Корольков\nГафер: Станислав Герасимов\nЗвукорежиссёр: Ксения Аблез\nХудожник по костюму: Валерия Сеина\nМонтажер: Олег Горовой\n\nAccount-director: Ксения Евстигнеева\nAccount-manager: Альбина Хузина\nAccount-manager: Елизавета Болясная"}], "dprofile": "https://dprofile.ru/case/134125/xroniki-izory", "thumb": "thumbs/xroniki-izory.jpg"}, {"slug": "tresnutye-3", "title": "Треснутые 3", "meta": "Дикси · 360 · 2023", "awards": "Silver Mercury 2024 — серебро (D01 Best Executed Digital Tool Campaign) · Red Apple 2024 — бронза ×3 (цифровой брендированный контент, Best Use of Sales Promo, креативная эффективность) · E+ Awards — бронза (Детский маркетинг) · Perspectum Awards — серебро (Best Sales Promotion Campaign) + 5 шорт-листов", "role": "автор концепции и сценария ТВ-ролика", "Задача": "Третий перезапуск собственного бренда «Треснутые»: акция и коллекция из 26 игрушек за каждые 600 ₽ в чеке. Механика напрямую работает на средний чек.", "Ограничения": "Третий заход подряд: нельзя повторяться и нельзя ломать узнаваемость. 26 игрушек уходили в производство до финала концепции. Без селебрити.", "Решение": "Кампания 360: концепция, ТВ-ролик, KV, иллюстрации, диджитал. Собственные персонажи вместо лицензии — легенда фэнтезийного мира, характер и суперсила у каждого.", "Результат": "Тендер выигран. Бренд пережил третью реинкарнацию и превратился в сериал. Показатели акции под NDA — называю на созвоне.", "video": [{"src": "media/tresnutye-3/tresnutye.mp4", "poster": "media/tresnutye-3/tresnutye.jpg"}], "blocks": [{"t": "img", "src": "media/tresnutye-3/01.jpg", "w": 1600, "h": 760}, {"t": "img", "src": "media/tresnutye-3/02.jpg", "w": 1600, "h": 1054}, {"t": "loop", "src": "media/tresnutye-3/03.mp4"}, {"t": "img", "src": "media/tresnutye-3/04.jpg", "w": 1600, "h": 1405}, {"t": "loop", "src": "media/tresnutye-3/05.mp4"}, {"t": "img", "src": "media/tresnutye-3/06.jpg", "w": 992, "h": 1600}, {"t": "img", "src": "media/tresnutye-3/07.jpg", "w": 1600, "h": 780}, {"t": "loop", "src": "media/tresnutye-3/08.mp4"}, {"t": "loop", "src": "media/tresnutye-3/09.mp4"}, {"t": "img", "src": "media/tresnutye-3/10.jpg", "w": 1600, "h": 1258}, {"t": "img", "src": "media/tresnutye-3/11.jpg", "w": 1600, "h": 621}, {"t": "img", "src": "media/tresnutye-3/12.jpg", "w": 1600, "h": 833}, {"t": "img", "src": "media/tresnutye-3/13.jpg", "w": 1600, "h": 1234}, {"t": "loop", "src": "media/tresnutye-3/14.mp4"}, {"t": "img", "src": "media/tresnutye-3/15.jpg", "w": 1597, "h": 1600}, {"t": "img", "src": "media/tresnutye-3/16.jpg", "w": 1600, "h": 1452}, {"t": "img", "src": "media/tresnutye-3/17.jpg", "w": 1600, "h": 1377}, {"t": "img", "src": "media/tresnutye-3/18.jpg", "w": 1600, "h": 1024}, {"t": "img", "src": "media/tresnutye-3/19.jpg", "w": 1600, "h": 240}, {"t": "img", "src": "media/tresnutye-3/20.jpg", "w": 1600, "h": 918}], "dprofile": "https://dprofile.ru/case/97913/tresnutye-3", "thumb": "thumbs/tresnutye-3.jpg"}, {"slug": "ozon-x-fandom-fest", "title": "Ozon Corp", "meta": "Ozon · Фандом Фэст · интеграция · 2023", "awards": "Silver Mercury 2025 — серебро (K12 Best Event Sponsorship) · бронза (K13 Best Event Branding) · Red Apple 2025 — бронза (A17 маркетплейсы и e-commerce)", "role": "автор концепции интеграции", "Задача": "Маркетплейсу нужно попасть в фандом-культуру, не притворяясь своим. Аудитория фестиваля мгновенно считывает фальшь и наказывает за неё.", "Ограничения": "Площадка фестиваля с жёстким графиком монтажа и своей аудиторией, которая не прощает рекламного тона.", "Решение": "Бренд-зона и интеграция, построенные на самоиронии: Ozon приходит не как спонсор с логотипом, а как участник со своим языком.", "Результат": "Фандом принял. Ирония засчитана, а бренд-зона стала точкой притяжения, а не проходной локацией.", "video": [], "blocks": [{"t": "img", "src": "media/ozon-x-fandom-fest/01.jpg", "w": 1600, "h": 750}, {"t": "img", "src": "media/ozon-x-fandom-fest/02.jpg", "w": 1440, "h": 1600}, {"t": "img", "src": "media/ozon-x-fandom-fest/03.jpg", "w": 1600, "h": 1242}, {"t": "embed", "src": "https://kinescope.io/embed/vpZ7k5FbjNcoyGDuq4TLZ8"}, {"t": "img", "src": "media/ozon-x-fandom-fest/04.jpg", "w": 1184, "h": 1600}, {"t": "img", "src": "media/ozon-x-fandom-fest/05.jpg", "w": 869, "h": 1600}, {"t": "img", "src": "media/ozon-x-fandom-fest/06.jpg", "w": 1600, "h": 799}, {"t": "img", "src": "media/ozon-x-fandom-fest/07.jpg", "w": 553, "h": 1600}, {"t": "img", "src": "media/ozon-x-fandom-fest/08.jpg", "w": 1000, "h": 1600}, {"t": "img", "src": "media/ozon-x-fandom-fest/09.jpg", "w": 923, "h": 1600}, {"t": "text", "text": "Команда проекта: \n\nкреативный директор – Андрей Яхновец, \nруководитель креативной группы – Павел Черкун, \nкопирайтер – Айгуль Бурганова,\nиллюстратор – Яна Воронина, \nдизайнер – Елена Захарова, \n3D-дизайнер – Егор Хомченко, \nаккаунт-менеджер – Зоя Колеватова, \nпроджект-менеджер – Григорий Шагламджян, \nпроджект-менеджер – Кирилл Шеховцов, \nаккаунт-директор – Евстигнеева Ксения,\nаккаунт-директор – Никитинская Ксения,\nCEO – Преображенская Ольга"}], "dprofile": "https://dprofile.ru/case/100178/ozon-x-fandom-fest", "thumb": "thumbs/ozon-x-fandom-fest.jpg"}, {"slug": "diksi-klipersy", "title": "Клиперсы", "meta": "Дикси · ТВ + KV · 2023", "awards": "Исследование «Нейротренд» / НейроВизор: лучшая реклама продуктового ритейла по замеру реакции аудитории", "role": "креатор — концепция, сценарий, тексты", "Задача": "Акция для школьников: значки для браслетов и кроксов за каждые 600 ₽ в чеке. Особое условие клиента — без инфлюенсеров.", "Ограничения": "Нельзя использовать инфлюенсеров. KV нужно было получить без отдельной съёмки — сняли фотосет прямо в смену ролика.", "Решение": "Пошёл в данные по поколению Альфа: 22% поисковых запросов — мемы. Если нельзя взять носителя тренда, надо стать самим трендом. Фонк-клип: мем про Доктора Ливси, дрифт, кроксы, панчи вместо рекламных сообщений, механика зарифмована нативно.", "Результат": "Лучшая реклама продуктового ритейла по нейромаркетинговому исследованию «Нейротренд» — независимый замер, а не жюри.", "video": [], "blocks": [{"t": "img", "src": "media/diksi-klipersy/01.jpg", "w": 1600, "h": 900}, {"t": "img", "src": "media/diksi-klipersy/02.jpg", "w": 1600, "h": 900}, {"t": "img", "src": "media/diksi-klipersy/03.jpg", "w": 1600, "h": 1025}, {"t": "img", "src": "media/diksi-klipersy/04.jpg", "w": 1600, "h": 736}, {"t": "img", "src": "media/diksi-klipersy/05.jpg", "w": 1600, "h": 1168}, {"t": "embed", "src": "https://kinescope.io/embed/5UaRgczewxzqjS86YGkTyX"}, {"t": "img", "src": "media/diksi-klipersy/06.jpg", "w": 1600, "h": 637}, {"t": "img", "src": "media/diksi-klipersy/07.jpg", "w": 1600, "h": 936}, {"t": "img", "src": "media/diksi-klipersy/08.jpg", "w": 1600, "h": 884}, {"t": "img", "src": "media/diksi-klipersy/09.jpg", "w": 1600, "h": 740}, {"t": "img", "src": "media/diksi-klipersy/10.jpg", "w": 1600, "h": 251}], "dprofile": "https://dprofile.ru/case/107155/diksi-klipersy", "thumb": "thumbs/diksi-klipersy.jpg"}, {"slug": "diksi-dino", "title": "Дикси Дино", "meta": "Дикси · лояльность · 2025", "awards": "Silver Mercury 2025 — шорт-лист (A10 Retail, A20 Baby Products) · Red Apple 2025 — шорт-лист (A07 Ритейл) · White Square 2025 — шорт-лист (A6 Campaign, A8 Retail Promotions)", "role": "creative group head", "Задача": "Ежегодная акция лояльности. Каждый год её ждут — и каждый год она обязана быть новой при том же бюджете.", "Ограничения": "Годовой цикл акции: старт нельзя сдвинуть, коллекция уходит в производство раньше финальных материалов.", "Решение": "Концепция, персонажи, носители и анимация вокруг динозавров: знакомая механика, новая вселенная.", "Результат": "Акция вышла в сеть. Пять шорт-листов трёх фестивалей при том же бюджете, что и годом раньше.", "video": [{"src": "media/diksi-dino/diksi-dino.mp4", "poster": "media/diksi-dino/diksi-dino.jpg"}], "blocks": [{"t": "img", "src": "media/diksi-dino/01.jpg", "w": 551, "h": 1600}, {"t": "loop", "src": "media/diksi-dino/02.mp4"}, {"t": "img", "src": "media/diksi-dino/03.jpg", "w": 1600, "h": 1217}, {"t": "loop", "src": "media/diksi-dino/04.mp4"}, {"t": "img", "src": "media/diksi-dino/05.jpg", "w": 722, "h": 1600}, {"t": "img", "src": "media/diksi-dino/06.jpg", "w": 1600, "h": 428}], "dprofile": "https://dprofile.ru/case/136560/diksi-dino", "thumb": "thumbs/diksi-dino.jpg"}, {"slug": "sinegrivyi-lev-talisman-fk-zenit", "title": "Синегривый лев", "meta": "ФК «Зенит» · талисман · 2025", "role": "креативный лидер проекта — руководил от стратегии до мерча", "Задача": "Клуб пришёл с ростовой куклой для матчей. Лев обнимал детей на фан-променаде, махал трибунам — и исчезал до следующей игры. Любят, но не запоминают.", "Ограничения": "Не сломать то, за что персонажа уже любят. Образ должен оставаться собой везде: в костюме на стадионе, в стикерпаке, в ТВ-графике, на полке магазина.", "Решение": "Из милого талисмана — в доброго хулигана. Характер, 2D- и 3D-образ, айдентика, мерч. И гороскоп — рабочий инструмент: он задаёт аниматорам и SMM рамку мимики и реакций.", "Результат": "У «Зенита» появился +1 игрок. Работает 365 дней в году, а не 90 минут в день матча.", "awards": "", "video": [], "blocks": [{"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/01.jpg", "w": 1600, "h": 900}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/02.jpg", "w": 1600, "h": 900}, {"t": "text", "text": "**Синегривый Лев: +1 игрок в составе ФК «Зенита»**\n\nКлуб пришёл к нам с ростовой куклой для матчевых активаций.\nМы вернули ему полноценного персонажа — со стратегией, характером,\nгороскопом, 2D- и 3D-образом, айдентикой и собственным мерчом."}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/03.jpg", "w": 1600, "h": 627}, {"t": "text", "text": "**Задача, которая была поставлена:** превратить героя в полноценный медиаактив клуба — \nперсонажа, который сам генерирует контент, собирает аудиторию и зарабатывает своим образом.\n\n"}, {"t": "embed", "src": "https://kinescope.io/embed/876g685UR1TJHSnujnVFnX"}, {"t": "text", "text": "**Синегривый Лев жил только в день матча:обнимал детей на фан-променаде, фотографировался,махал трибунам — и исчезал до следующей игры**\n\nДобрый, милый, всеми любимый — и при этом невидимый за пределами стадиона.\nРостовая кукла работала аниматором, но не работала брендом: без стратегии, без характера,\nбез единого визуального языка, без коммерческого потенциала."}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/04.jpg", "w": 1600, "h": 900}, {"t": "text", "text": "**У персонажа появилась собственная айдентика:** знак-голова героя, шрифтовой логотип,\nкобрендинговые версии с эмблемой ФК «Зенит», фирменная пара шрифтов\nDela Gothic One + Nunito Sans, фирменная цветовая палитра и правила для всех носителей."}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/05.jpg", "w": 1600, "h": 900}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/06.jpg", "w": 1600, "h": 900}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/07.jpg", "w": 1600, "h": 900}, {"t": "text", "text": "**От милого талисмана — к доброму хулигануИсследование показало:** Льва любят, но не запоминают.\nМилота без характера не даёт ни виральности, ни медиаповодов.\nМы пересобрали платформу персонажа — бережно, не ломая то, за что его полюбили."}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/08.jpg", "w": 1600, "h": 900}, {"t": "text", "text": "**Мы перебрали десятки пластик и пропорций, чтобы найти образ, который остаётся собой везде: **\nв костюме на стадионе, в стикерпаке, в ТВ-графике и на полке магазина. \nПоиск характера в эскизах: от «слишком спортивного» до «слишком мягкого» — \nи точное попадание."}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/09.jpg", "w": 1600, "h": 486}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/10.jpg", "w": 1600, "h": 900}, {"t": "text", "text": "**У Льва есть даже гороскоп**\n\nЛичный бренд — это глубина проработки. Мы просчитали астрологический портрет персонажа:\nСолнце в Весах — стремление объединять и уравновешивать энергию толпы; асцендент в Близнецах —\nартистизм, пластика и мгновенная реакция; Луна во Льве — тепло, щедрость и любовь к празднику.\n\nЭто не шутка, а рабочий инструмент: гороскоп задаёт аниматорам и SMM-команде рамку мимики,\nпластики и реакций — Лев ведёт себя одинаково «в теле» и в соцсетях."}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/11.jpg", "w": 1600, "h": 900}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/12.jpg", "w": 1600, "h": 900}, {"t": "row", "items": [{"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/13.jpg", "w": 1193, "h": 1600}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/14.jpg", "w": 1349, "h": 1600}]}, {"t": "text", "text": "**Мерч, который хочется носить, а не только «болеть»**\n\nФлаффи-капсула с фактурой гривы, детская коллекция с леттерингом и знаком Льва:\nхуди, бомберы, панамы, сумки и тапки. Персонаж перестал быть картинкой —\nон стал продуктом на полке клубного магазина."}, {"t": "row", "items": [{"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/15.jpg", "w": 1036, "h": 1600}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/16.jpg", "w": 1200, "h": 1600}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/17.jpg", "w": 1200, "h": 1600}]}, {"t": "row", "items": [{"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/18.jpg", "w": 1200, "h": 1600}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/19.jpg", "w": 1131, "h": 1600}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/20.jpg", "w": 1106, "h": 1600}]}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/21.jpg", "w": 1600, "h": 893}, {"t": "row", "items": [{"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/22.jpg", "w": 1147, "h": 1600}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/23.jpg", "w": 1147, "h": 1600}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/24.jpg", "w": 1147, "h": 1600}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/25.jpg", "w": 1147, "h": 1600}]}, {"t": "row", "items": [{"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/26.jpg", "w": 1147, "h": 1600}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/27.jpg", "w": 1147, "h": 1600}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/28.jpg", "w": 1147, "h": 1600}]}, {"t": "text", "text": "**У ФК «Зенит» появился +1 игрок:**\nактив, который работает 365 дней в году —\nа не 90 минут в день матча."}, {"t": "img", "src": "media/sinegrivyi-lev-talisman-fk-zenit/29.jpg", "w": 1600, "h": 900}], "dprofile": "https://dprofile.ru/case/193712/sinegrivyi-lev-talisman-fk-zenit", "thumb": "thumbs/sinegrivyi-lev-talisman-fk-zenit.jpg"}, {"slug": "purr-love", "title": "Purr Love", "meta": "Брендинг · 2025", "awards": "", "role": "creative group head", "Задача": "Бренду товаров для питомцев нужна не упаковка, а позиционирование: чем он отличается от полки одинаковых.", "Ограничения": "Позиционирование должно было читаться прямо с полки, без объясняющих текстов.", "Решение": "Исследование и опросы показали: хозяева относятся к питомцам как к детям. Отсюда позиционирование «как для детей» и айдентика на его основе.", "Результат": "Бренд говорит о питомцах так, как хозяева о них думают.", "video": [], "blocks": [{"t": "img", "src": "media/purr-love/01.jpg", "w": 1600, "h": 896}, {"t": "img", "src": "media/purr-love/02.jpg", "w": 1600, "h": 900}, {"t": "img", "src": "media/purr-love/03.jpg", "w": 1600, "h": 900}, {"t": "img", "src": "media/purr-love/04.jpg", "w": 1600, "h": 900}, {"t": "img", "src": "media/purr-love/05.jpg", "w": 1600, "h": 900}, {"t": "text", "text": "**Команда проекта**\nCreative Director: Андрей Яхновец\n\nArt-director: Антон Фрос\nCreative Group Head: Павел Черкун\nStrategist: Андрей Кошкин\nGraphic Designer: Регина Хафизова\nGraphic Designer: Ольга Пырегова\nCopywriter: Айгуль Бурганова\nAccount-director: Ксения Евстигнеева\nAccount manager: Ольга Горельченко\nProject manager: Софья Котлярова"}], "dprofile": "https://dprofile.ru/case/136128/purr-love", "thumb": "thumbs/purr-love.jpg"}, {"slug": "dogs", "title": "DOGS.", "meta": "Креативный SMM · 2019", "awards": "", "role": "креатор — контент и виральные форматы", "Задача": "Молодому бренду нужна была узнаваемость без медийного бюджета.", "Ограничения": "Продакшн на минимальных деньгах: всё снимается и монтируется внутри.", "Решение": "Креативный SMM на виральных форматах: контент, который репостят, а не пролистывают.", "Результат": "Первая школа: виральность как замена бюджету.", "video": [{"src": "media/dogs/dogs-1.mp4", "poster": "media/dogs/dogs-1.jpg"}, {"src": "media/dogs/dogs-2.mp4", "poster": "media/dogs/dogs-2.jpg"}, {"src": "media/dogs/dogs-3.mp4", "poster": "media/dogs/dogs-3.jpg"}], "blocks": [{"t": "text", "text": "«Бесконечный» хот-дог в профиле Instagram, промокоды в постах, контент-план на месяц в одном видео. По моим сведениям, кейс стал референсом минимум для двух проектов других агентств."}, {"t": "img", "src": "media/dogs/profile.jpg", "w": 1595, "h": 1600}], "dprofile": null, "thumb": "thumbs/dogs.jpg"}];
